package com.procurement.purchaseorder.service;import com.procurement.common.exception.*;import com.procurement.common.response.*;import com.procurement.purchaseorder.dto.request.*;import com.procurement.purchaseorder.dto.response.*;import com.procurement.purchaseorder.entity.*;import com.procurement.purchaseorder.exception.*;import com.procurement.purchaseorder.mapper.*;import com.procurement.purchaseorder.repository.*;import com.procurement.purchaseorder.specification.*;import com.procurement.quotationcomparison.entity.*;import com.procurement.quotationcomparison.repository.*;import com.procurement.vendorquotation.entity.*;import com.procurement.vendorquotation.repository.*;import org.springframework.data.domain.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;@Service public class PurchaseOrderServiceImpl implements PurchaseOrderService{private final PurchaseOrderRepository repo;private final PurchaseOrderLineRepository lines;private final PurchaseOrderAttachmentRepository attachments;private final PurchaseOrderHistoryRepository history;private final QuotationComparisonRepository comparisons;private final QuotationComparisonLineRepository comparisonLines;private final VendorQuotationLineRepository quotationLines;private final PurchaseOrderMapper mapper;private final com.procurement.procurement.scope.service.ProcurementScopeService scopeService;public PurchaseOrderServiceImpl(PurchaseOrderRepository r,PurchaseOrderLineRepository l,PurchaseOrderAttachmentRepository a,PurchaseOrderHistoryRepository h,QuotationComparisonRepository c,QuotationComparisonLineRepository cl,VendorQuotationLineRepository ql,PurchaseOrderMapper m,com.procurement.procurement.scope.service.ProcurementScopeService scopeService){repo=r;lines=l;attachments=a;history=h;comparisons=c;comparisonLines=cl;quotationLines=ql;mapper=m;this.scopeService=scopeService;}private String user(){var a=SecurityContextHolder.getContext().getAuthentication();return a==null?"system":a.getName();}private PurchaseOrder find(Long id){return repo.findById(id).orElseThrow(()->new PurchaseOrderNotFoundException(id));}private void record(PurchaseOrder p,String action,PurchaseOrderStatus old,PurchaseOrderStatus n){history.save(PurchaseOrderHistory.builder().purchaseOrder(p).action(action).oldStatus(old).newStatus(n).remarks(action).build());}private BigDecimal n(BigDecimal x){return x==null?BigDecimal.ZERO:x;}
@Transactional public PurchaseOrderResponse generate(Long comparisonId,PurchaseOrderRequest r){var c=comparisons.findById(comparisonId).orElseThrow(()->new ResourceNotFoundException("Comparison not found: "+comparisonId));if(c.getStatus()!=ComparisonStatus.APPROVED)throw new ConflictException("Comparison must be APPROVED");if(repo.existsByQuotationComparisonId(comparisonId))throw new ConflictException("Purchase order already exists");var winner=comparisonLines.findByComparisonIdOrderByRankAsc(comparisonId).stream().filter(QuotationComparisonLine::getRecommended).findFirst().orElseThrow(()->new ConflictException("Winning quotation not found")).getVendorQuotation();if(winner.getStatus()!=VendorQuotationStatus.ACCEPTED||!"ACTIVE".equalsIgnoreCase(winner.getVendor().getStatus()))throw new ConflictException("Winning vendor quotation is not accepted or vendor is inactive");if(r.expectedDeliveryDate().isBefore(LocalDate.now()))throw new BadRequestException("Expected delivery date cannot be before order date");var p=PurchaseOrder.builder().poNumber("PO-"+Year.now().getValue()+"-"+String.format("%06d",repo.count()+1)).quotationComparison(c).vendorQuotation(winner).vendor(winner.getVendor()).purchaseRequest(c.getRfq().getPurchaseRequest()).department(c.getRfq().getPurchaseRequest().getDepartment()).costCenter(c.getRfq().getPurchaseRequest().getCostCenter()).orderDate(LocalDate.now()).expectedDeliveryDate(r.expectedDeliveryDate()).currency(winner.getCurrency()).paymentTerms(winner.getPaymentTerms()).deliveryAddress(r.deliveryAddress()).billingAddress(r.billingAddress()).remarks(r.remarks()).createdBy(user()).updatedBy(user()).status(PurchaseOrderStatus.GENERATED).build();p=repo.save(p);for(var ql:quotationLines.findByVendorQuotationId(winner.getId()))lines.save(PurchaseOrderLine.builder().purchaseOrder(p).product(ql.getProduct()).quantityOrdered(ql.getQuantity()).unitPrice(ql.getUnitPrice()).discountPercentage(ql.getDiscountPercentage()).taxPercentage(ql.getTaxPercentage()).lineAmount(ql.getLineAmount()).build());p.setSubtotal(winner.getSubtotal());p.setDiscountAmount(winner.getDiscountAmount());p.setTaxAmount(winner.getTaxAmount());p.setShippingCharges(winner.getShippingCharges());p.setOtherCharges(winner.getOtherCharges());p.setGrandTotal(winner.getGrandTotal());p=repo.save(p);record(p,"GENERATED",null,p.getStatus());return mapper.po(p);}
@Transactional(readOnly=true)public PageResponse<PurchaseOrderResponse>search(String k,Long v,PurchaseOrderStatus s,Pageable p){var spec=PurchaseOrderSpecification.search(k,v,s);var catSpec=PurchaseOrderSpecification.categoryIn(scopeService.myCategoryIds());if(catSpec!=null)spec=spec.and(catSpec);Page<PurchaseOrderResponse>x=repo.findAll(spec,p).map(mapper::po);return new PageResponse<>(x.getContent(),x.getNumber(),x.getSize(),x.getTotalElements(),x.getTotalPages(),x.isLast());}@Transactional(readOnly=true)public PageResponse<PurchaseOrderResponse>searchByRequest(Long purchaseRequestId,Pageable p){org.springframework.data.jpa.domain.Specification<PurchaseOrder>spec=(r,q,b)->b.equal(r.get("purchaseRequest").get("id"),purchaseRequestId);Page<PurchaseOrderResponse>x=repo.findAll(spec,p).map(mapper::po);return new PageResponse<>(x.getContent(),x.getNumber(),x.getSize(),x.getTotalElements(),x.getTotalPages(),x.isLast());}@Transactional(readOnly=true)public PurchaseOrderResponse get(Long id){return mapper.po(find(id));}@Transactional public PurchaseOrderResponse update(Long id,PurchaseOrderRequest r){var p=find(id);if(p.getStatus()!=PurchaseOrderStatus.DRAFT&&p.getStatus()!=PurchaseOrderStatus.GENERATED)throw new ConflictException("Purchase order cannot be edited");p.setExpectedDeliveryDate(r.expectedDeliveryDate());p.setDeliveryAddress(r.deliveryAddress());p.setBillingAddress(r.billingAddress());p.setRemarks(r.remarks());return mapper.po(repo.save(p));}@Transactional public void delete(Long id){var p=find(id);if(p.getStatus()!=PurchaseOrderStatus.DRAFT&&p.getStatus()!=PurchaseOrderStatus.GENERATED)throw new ConflictException("Purchase order cannot be deleted");repo.delete(p);}
private PurchaseOrder transition(Long id,PurchaseOrderStatus from,PurchaseOrderStatus to,String action){var p=find(id);if(p.getStatus()!=from)throw new ConflictException("Invalid purchase order status transition");p.setStatus(to);p.setUpdatedBy(user());record(p,action,from,to);return repo.save(p);}@Transactional public PurchaseOrderResponse send(Long id){return mapper.po(transition(id,PurchaseOrderStatus.GENERATED,PurchaseOrderStatus.SENT,"SENT"));}@Transactional public PurchaseOrderResponse acknowledge(Long id){return mapper.po(transition(id,PurchaseOrderStatus.SENT,PurchaseOrderStatus.ACKNOWLEDGED,"ACKNOWLEDGED"));}@Transactional public PurchaseOrderResponse cancel(Long id){var p=find(id);if(p.getStatus()==PurchaseOrderStatus.CANCELLED||p.getStatus()==PurchaseOrderStatus.CLOSED)throw new ConflictException("Purchase order cannot be cancelled");return mapper.po(transition(id,p.getStatus(),PurchaseOrderStatus.CANCELLED,"CANCELLED"));}@Transactional public PurchaseOrderResponse close(Long id){return mapper.po(transition(id,PurchaseOrderStatus.FULLY_RECEIVED,PurchaseOrderStatus.CLOSED,"CLOSED"));}
@Transactional(readOnly=true)public PageResponse<PurchaseOrderLineResponse>lines(Long id,Pageable p){var z=lines.findByPurchaseOrderId(id).stream().map(mapper::line).toList();var x=new PageImpl<>(z,p,z.size());return new PageResponse<>(x.getContent(),x.getNumber(),x.getSize(),x.getTotalElements(),x.getTotalPages(),x.isLast());}@Transactional(readOnly=true)public PurchaseOrderLineResponse line(Long id){return lines.findById(id).map(mapper::line).orElseThrow(()->new ResourceNotFoundException("Purchase order line not found: "+id));}@Transactional public PurchaseOrderAttachmentResponse attachment(Long id,PurchaseOrderAttachmentRequest r){var p=find(id);return mapper.attachment(attachments.save(PurchaseOrderAttachment.builder().purchaseOrder(p).fileName(r.fileName()).filePath(r.filePath()).fileType(r.fileType()).build()));}@Transactional(readOnly=true)public PageResponse<PurchaseOrderAttachmentResponse>attachments(Long id,Pageable p){var z=attachments.findByPurchaseOrderId(id).stream().map(mapper::attachment).toList();var x=new PageImpl<>(z,p,z.size());return new PageResponse<>(x.getContent(),x.getNumber(),x.getSize(),x.getTotalElements(),x.getTotalPages(),x.isLast());}@Transactional public void deleteAttachment(Long id,Long aid){var a=attachments.findById(aid).orElseThrow(()->new ResourceNotFoundException("Attachment not found: "+aid));if(!a.getPurchaseOrder().getId().equals(id))throw new BadRequestException("Attachment does not belong to purchase order");attachments.delete(a);}@Transactional(readOnly=true)public PageResponse<PurchaseOrderHistoryResponse>history(Long id,Pageable p){var z=history.findByPurchaseOrderIdOrderByPerformedAtAsc(id).stream().map(mapper::history).toList();var x=new PageImpl<>(z,p,z.size());return new PageResponse<>(x.getContent(),x.getNumber(),x.getSize(),x.getTotalElements(),x.getTotalPages(),x.isLast());}}
